def max_product(arr):
    data = {"array": arr, "elements": []}
    if len(arr) < 2:
        return None
    arr.sort()
    data["elements"] = [arr[-1], arr[-2]]
    data["max_product"] = data["elements"][0] * data["elements"][1]
    return data["max_product"]
